@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@500;600;700&display=swap');
:root{--red:#c92825;--red-dark:#ad201f;--red-soft:#fff0ee;--ink:#22252a;--muted:#777d86;--line:#e9eaec;--paper:#fff;--bg:#f4f5f6;--green:#249563;--shadow:0 12px 30px #22252a0c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans',Arial,sans-serif;font-size:14px}button,input{font:inherit}button{cursor:pointer}.app-shell{min-height:100vh}.topbar{height:68px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 32px;gap:40px;position:sticky;top:0;z-index:10}.brand{border:0;background:none;display:flex;align-items:center;gap:10px;padding:0;min-width:176px;color:var(--ink)}.brand-mark{height:35px;width:35px;display:grid;place-items:center;background:var(--red);color:white;border-radius:10px;font-family:'Space Grotesk';font-weight:700;font-size:23px;transform:rotate(-5deg);box-shadow:inset -3px -3px 0 #8e161857}.brand-name{font-family:'Space Grotesk';font-size:21px;font-weight:700;letter-spacing:-1.3px}.brand-name span{color:var(--red)}.top-links{display:flex;height:100%;gap:30px}.nav-link{height:100%;padding:0 4px;border:0;border-bottom:3px solid transparent;background:none;color:#747983;font-weight:700}.nav-link:hover,.nav-link.active{color:var(--red)}.nav-link.active{border-bottom-color:var(--red)}.top-actions{margin-left:auto;display:flex;align-items:center;gap:17px}.search-box{height:38px;width:230px;border:1px solid #e6e7e9;border-radius:8px;display:flex;align-items:center;padding:0 11px;gap:9px;color:#8a8e95;background:#fafafa}.search-box span{font-size:24px;line-height:1;transform:rotate(-20deg)}.search-box input{width:100%;border:0;outline:0;background:transparent;color:var(--ink);font-size:13px}.avatar-pill{height:40px;border:1px solid var(--line);border-radius:8px;background:#fff;display:flex;align-items:center;gap:9px;padding:4px 11px;font-weight:700}.mini-avatar{background:#ffdfb4;width:27px;height:27px;border-radius:7px;display:grid;place-items:center;color:#8b5138;font-size:19px}.chevron{color:#858991}.mobile-menu{display:none;border:0;background:none;font-size:22px}.layout{display:flex;max-width:1600px;margin:auto}.sidebar{width:224px;flex-shrink:0;padding:27px 15px 20px 24px;min-height:calc(100vh - 68px);background:#fafafa;border-right:1px solid #ececee;display:flex;flex-direction:column}.side-group{margin-bottom:26px}.side-label{color:#a1a5ac;letter-spacing:1.15px;font-size:10px;font-weight:800;margin:0 0 10px 12px}.side-link{width:100%;height:42px;border:0;border-radius:7px;display:flex;align-items:center;text-align:left;padding:0 12px;gap:13px;background:transparent;color:#626771;font-weight:600;margin:3px 0}.side-link>span{width:18px;text-align:center;font-size:19px;color:#868b93}.side-link:hover,.side-link.selected{background:#ffefed;color:var(--red)}.side-link.selected>span,.side-link:hover>span{color:var(--red)}.tiny-count{font-style:normal;font-size:10px;margin-left:auto;border-radius:9px;background:#fff;color:#aaa;padding:2px 6px}.sidebar-bottom{margin-top:auto;border-top:1px solid var(--line);padding:19px 4px 4px;display:flex;gap:10px;align-items:flex-start;font-size:11px}.online-dot{margin-top:4px;width:8px;height:8px;border-radius:50%;background:#39b879;box-shadow:0 0 0 3px #39b87922}.sidebar-bottom b,.sidebar-bottom small{display:block}.sidebar-bottom b{font-size:11px}.sidebar-bottom small{color:#90959d;margin-top:4px}.main-content{min-width:0;flex:1;padding:28px 36px 64px;max-width:1350px;margin:0 auto;width:calc(100% - 224px)}.hero{background:linear-gradient(112deg,#9f201c 0%,#ce3029 58%,#e54a3d 100%);height:300px;border-radius:13px;color:white;position:relative;overflow:hidden;padding:39px 42px;box-shadow:0 14px 26px #a526252b}.hero:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 75% 30%,#ffb15950,transparent 36%),linear-gradient(130deg,transparent 40%,#7e171936 100%)}.hero-copy{position:relative;z-index:2;max-width:52%}.eyebrow{font-size:10px;letter-spacing:1.8px;font-weight:800;color:#ffd2c9}.hero h1{font-family:'Space Grotesk';font-size:39px;letter-spacing:-1.6px;line-height:1.08;margin:14px 0 12px;max-width:400px}.hero p{font-size:13px;line-height:1.65;color:#ffe9e5;max-width:370px;margin:0}.hero-buttons{display:flex;gap:10px;margin-top:22px}.btn{border:0;border-radius:7px;padding:11px 17px;font-weight:800;display:inline-flex;align-items:center;justify-content:center;gap:7px;transition:transform .16s,background .16s}.btn:hover{transform:translateY(-2px)}.btn-light{background:#fff;color:var(--red)}.btn-ghost{background:#ffffff1a;border:1px solid #ffffff5c;color:white}.btn-red{background:var(--red);color:#fff}.hero-art{position:absolute;right:5%;top:0;width:44%;height:100%;display:flex;justify-content:center;align-items:center;perspective:700px}.art-island{position:relative;width:360px;height:220px;transform:rotateX(53deg) rotateZ(-34deg);transform-style:preserve-3d}.art-ground{position:absolute;inset:27px 20px 10px;background:linear-gradient(135deg,#83b85b,#4f984c);border:8px solid #73b95c;border-radius:15px;box-shadow:0 24px 0 #397b42,0 40px 30px #67120f7a}.art-road{position:absolute;z-index:2;left:45%;top:27px;width:43px;height:178px;background:#8e8d86;border-left:5px solid #d5c9a7;border-right:5px solid #d5c9a7;transform:translateZ(4px)}.art-road:after{content:'';position:absolute;left:15px;top:0;height:100%;border-left:3px dashed #fff8c8}.art-block{position:absolute;z-index:3;transform:translateZ(24px);width:46px;height:50px;background:#f8bf4d;box-shadow:inset -12px -10px #d5983b}.art-block:before{content:'';position:absolute;width:100%;height:15px;top:-15px;background:#ffdd79;transform:skewY(-27deg);transform-origin:bottom}.art-block:after{content:'';position:absolute;right:-15px;top:-7px;width:15px;height:50px;background:#c47d2f;transform:skewY(-45deg)}.art-block.one{left:73px;top:76px}.art-block.two{right:60px;top:58px;background:#e95643;box-shadow:inset -12px -10px #bd3831}.art-block.three{left:150px;top:138px;width:38px;height:38px;background:#418bd0;box-shadow:inset -10px -8px #2b67a7}.art-player{position:absolute;z-index:4;left:47%;top:45%;transform:translateZ(70px) rotateZ(34deg);height:76px;width:38px}.art-player .head{height:23px;width:23px;background:#f5bd8c;border-radius:4px;margin:auto;box-shadow:inset -4px -3px #cd8d64}.art-player .torso{height:30px;width:34px;background:#fff;border-radius:5px;margin:2px auto 0;box-shadow:inset -8px -2px #dbe1e6}.art-player .legs{display:flex;justify-content:center;gap:4px}.art-player .legs i{display:block;height:23px;width:13px;background:#263a58;border-radius:2px}.art-sun{position:absolute;right:14%;top:15%;font-size:37px;filter:drop-shadow(0 5px 12px #fff3a7)}.section-head{display:flex;align-items:end;justify-content:space-between;margin:29px 0 15px}.section-title{font-family:'Space Grotesk';font-size:20px;letter-spacing:-.55px;margin:0}.section-sub{color:var(--muted);font-size:12px;margin:5px 0 0}.text-button{border:0;background:transparent;color:var(--red);font-weight:800;font-size:12px;padding:6px}.game-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.game-card{background:white;border:1px solid #ebeced;border-radius:9px;overflow:hidden;cursor:pointer;transition:transform .18s,box-shadow .18s;min-width:0}.game-card:hover{transform:translateY(-4px);box-shadow:0 12px 25px #20252b16}.thumb{height:132px;position:relative;overflow:hidden;background:#d3e8f4}.thumb:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#17232c44,transparent 58%)}.thumb-tag{position:absolute;z-index:2;top:9px;left:9px;font-size:9px;letter-spacing:.5px;background:#fff;color:#52565e;padding:5px 7px;border-radius:4px;font-weight:800}.thumb-players{position:absolute;bottom:9px;left:10px;z-index:2;color:#fff;font-size:10px;font-weight:700;text-shadow:0 1px 3px #000}.thumb-title{position:absolute;bottom:9px;right:10px;z-index:2;color:#fff;font-weight:800;font-size:11px;text-shadow:0 1px 4px #000}.card-info{padding:10px 11px 11px}.card-title{font-weight:800;font-size:12px;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-meta{display:flex;align-items:center;justify-content:space-between;color:#8b9098;font-size:10px;margin-top:8px}.rating{color:#b17b13}.play-triangle{color:var(--red)}.thumb-disaster{background:linear-gradient(#8bc4e3 0 57%,#6ca45b 57%)}.thumb-disaster .scene{position:absolute;inset:0;background:linear-gradient(167deg,transparent 44%,#688e47 45% 68%,#4a7142 69%);}.thumb-disaster .scene:before{content:'';position:absolute;left:46%;top:22%;width:32px;height:46px;background:#cf5646;box-shadow:9px -16px #a13c34,35px 9px #f4c252,-49px 17px #e6dabe;transform:skewY(-12deg)}.thumb-disaster .scene:after{content:'☁';position:absolute;top:12%;left:18%;font-size:53px;color:#fff9}.thumb-pizza{background:linear-gradient(#bee5f1 0 58%,#72a65a 58%)}.thumb-pizza .scene{position:absolute;inset:0;background:linear-gradient(172deg,transparent 47%,#96b965 48% 67%,#73a050 68%)}.thumb-pizza .scene:before{content:'';position:absolute;left:23%;top:28%;width:98px;height:47px;background:#e4a344;border-top:18px solid #f1d080;box-shadow:0 10px 0 #bd7036;transform:skewY(-5deg)}.thumb-cross{background:linear-gradient(#70bce0 0 58%,#5f984a 58%)}.thumb-cross .scene{position:absolute;inset:0;background:linear-gradient(160deg,transparent 45%,#7eaa54 46% 65%,#528640 66%)}.thumb-cross .scene:before{content:'';position:absolute;left:42%;top:23%;width:33px;height:57px;background:#9c7353;box-shadow:9px -13px #73513d,52px 25px #be5548,-49px 30px #b19d70;transform:skewY(-12deg)}.thumb-obby{background:linear-gradient(#b8dcee 0 58%,#58a1ca 59%)}.thumb-obby .scene{position:absolute;inset:0;background:linear-gradient(165deg,transparent 48%,#5678bf 49%)}.thumb-obby .scene:before{content:'';position:absolute;left:20%;top:27%;width:42px;height:20px;background:#f7d752;box-shadow:47px 22px #ef7c59,100px -7px #66d0b1,145px 28px #d772cf;transform:skewY(-11deg)}.explore-strip{margin-top:28px;background:#fff;border:1px solid var(--line);border-radius:9px;padding:17px 19px;display:flex;align-items:center;gap:14px}.strip-icon{width:40px;height:40px;border-radius:9px;background:#fff1ef;display:grid;place-items:center;color:var(--red);font-size:21px}.explore-strip strong{font-size:13px}.explore-strip p{margin:3px 0 0;color:var(--muted);font-size:11px}.explore-strip .text-button{margin-left:auto}.page-heading{display:flex;justify-content:space-between;align-items:end;margin:10px 0 23px}.page-heading h1{font:700 29px 'Space Grotesk';letter-spacing:-1px;margin:0}.page-heading p{margin:6px 0 0;color:var(--muted);font-size:13px}.filter-row{display:flex;gap:8px;margin-bottom:17px;flex-wrap:wrap}.filter-chip{border:1px solid #e5e6e8;border-radius:20px;background:white;padding:8px 14px;color:#626770;font-size:11px;font-weight:700}.filter-chip.active{background:#27292d;color:white;border-color:#27292d}.empty-state{grid-column:1/-1;background:white;border:1px dashed #d9dbde;border-radius:10px;text-align:center;padding:50px 20px;color:#858b94}.empty-state strong{display:block;color:#34383e;font-size:15px;margin-bottom:6px}.simple-panel{background:white;border:1px solid var(--line);border-radius:11px;padding:26px;max-width:720px}.simple-panel h2{font:700 20px 'Space Grotesk';margin:0 0 7px}.simple-panel p{color:#737983;line-height:1.7}.avatar-preview{display:flex;align-items:center;gap:20px;margin-top:20px}.avatar-big{height:118px;width:96px;border-radius:14px;background:#eef5f7;position:relative;display:grid;place-items:center;font-size:60px}.swatch{height:32px;width:32px;border-radius:8px;border:2px solid #fff;box-shadow:0 0 0 1px #ddd;display:inline-block;margin:4px;cursor:pointer}.toast{position:fixed;left:50%;bottom:22px;z-index:30;transform:translate(-50%,20px);background:#24272c;color:white;padding:11px 16px;border-radius:7px;font-size:12px;font-weight:700;opacity:0;transition:.2s;pointer-events:none;box-shadow:0 8px 20px #0003}.toast.show{opacity:1;transform:translate(-50%,0)}
/* playable 3D canvas view */
.game-overlay{position:fixed;inset:0;background:#111922;z-index:20;display:none;color:white}.game-overlay.open{display:block}.game-stage{position:absolute;inset:0;overflow:hidden}.game-canvas{position:absolute;inset:0;width:100%;height:100%;touch-action:none}.game-top{position:absolute;left:22px;right:22px;top:18px;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.game-top>*{pointer-events:auto}.game-brand{display:flex;align-items:center;gap:10px}.game-brand .brand-mark{height:33px;width:33px;border-radius:8px}.game-label{font-size:12px;font-weight:800;text-shadow:0 2px 6px #0008}.game-label small{display:block;color:#ffffffaf;font-size:10px;margin-top:3px}.game-actions{display:flex;gap:8px}.game-icon-btn{height:38px;width:40px;border-radius:8px;border:1px solid #ffffff55;background:#17212baa;color:white;font-size:16px;backdrop-filter:blur(8px)}.game-hud{position:absolute;left:22px;top:84px;display:flex;flex-direction:column;gap:9px}.hud-card{min-width:155px;border:1px solid #ffffff42;background:#14212bbd;border-radius:8px;padding:10px 13px;backdrop-filter:blur(8px);box-shadow:0 5px 18px #0002}.hud-card small{display:block;text-transform:uppercase;letter-spacing:1px;font-size:9px;color:#d4e2e8;font-weight:800}.hud-card strong{display:block;font-size:16px;margin-top:4px}.hud-card .progress{height:4px;background:#ffffff35;border-radius:4px;margin-top:7px;overflow:hidden}.hud-card .progress i{height:100%;width:100%;display:block;background:#7de0aa;transition:width .2s}.game-bottom{position:absolute;bottom:18px;left:20px;right:20px;display:flex;justify-content:space-between;align-items:end;pointer-events:none}.game-bottom>*{pointer-events:auto}.controls-hint{background:#15222ab8;border:1px solid #ffffff35;padding:9px 12px;border-radius:7px;font-size:10px;color:#f1f5f6;backdrop-filter:blur(7px)}.controls-hint b{color:#fff}.game-exit{background:#fff;color:#333;border:0;border-radius:7px;font-weight:800;padding:11px 16px}.mobile-controls{display:none;align-items:end;gap:14px}.dpad{display:grid;grid-template-columns:38px 38px 38px;grid-template-rows:38px 38px 38px;gap:3px}.touch-btn{border:1px solid #fff7;border-radius:7px;background:#15222aaa;color:#fff;font-weight:800;touch-action:none;backdrop-filter:blur(5px)}.touch-btn.up{grid-area:1/2}.touch-btn.left{grid-area:2/1}.touch-btn.down{grid-area:2/2}.touch-btn.right{grid-area:2/3}.jump-btn{height:62px;width:62px;border-radius:50%;background:#c92825dd;font-size:10px}.game-modal{position:absolute;inset:0;z-index:3;background:#10171ba8;display:grid;place-items:center;backdrop-filter:blur(4px)}.modal-card{width:min(410px,calc(100% - 34px));background:white;color:#282b30;border-radius:12px;padding:27px;box-shadow:0 20px 80px #0005}.modal-card h2{font:700 23px 'Space Grotesk';margin:0 0 8px}.modal-card p{color:#747a83;line-height:1.6;font-size:13px}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:22px}.modal-actions .btn{font-size:12px}.modal-dark{background:#f1f2f4;color:#50555c}
@media(max-width:1050px){.main-content{padding:25px 24px 50px}.hero{height:282px;padding:33px}.hero-art{right:-2%;transform:scale(.88)}.game-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.thumb{height:150px}.sidebar{width:195px}.main-content{width:calc(100% - 195px)}}
@media(max-width:700px){.topbar{height:58px;padding:0 15px;gap:12px}.brand{min-width:0;gap:7px}.brand-mark{height:32px;width:32px}.brand-name{font-size:18px}.mobile-menu{display:block;color:#444}.top-links{display:none;position:absolute;top:58px;left:0;right:0;height:auto;background:white;padding:9px 14px;border-bottom:1px solid var(--line);gap:8px;box-shadow:0 8px 15px #0001}.top-links.mobile-open{display:flex}.nav-link{height:38px;padding:0 10px;border-bottom-width:2px}.top-actions{gap:8px}.search-box{width:38px;border:0;background:transparent;padding:0;justify-content:center}.search-box input{display:none}.search-box span{font-size:24px}.avatar-pill{height:35px;padding:3px 7px;font-size:11px;gap:5px}.avatar-pill .mini-avatar{height:25px;width:25px}.sidebar{display:none}.main-content{width:100%;padding:18px 14px 42px}.hero{height:315px;padding:24px 22px;border-radius:10px}.hero-copy{max-width:75%}.hero h1{font-size:30px;max-width:280px}.hero p{max-width:285px;font-size:12px}.hero-art{width:50%;right:-18%;top:40px;transform:scale(.55);transform-origin:center}.hero-buttons{margin-top:17px}.btn{padding:10px 12px;font-size:11px}.section-head{margin-top:24px}.section-title{font-size:18px}.game-grid{gap:10px}.thumb{height:112px}.card-info{padding:9px}.card-title{font-size:11px}.card-meta{font-size:9px}.page-heading h1{font-size:25px}.game-top{left:12px;right:12px;top:12px}.game-hud{left:12px;top:65px}.hud-card{min-width:126px;padding:8px 10px}.game-bottom{left:12px;right:12px;bottom:12px}.controls-hint{display:none}.mobile-controls{display:flex}.game-exit{font-size:11px;padding:10px 13px}.game-actions .game-icon-btn{height:35px;width:36px}}
@media(max-width:380px){.hero{height:330px}.hero-copy{max-width:85%}.hero-art{opacity:.55;right:-35%;top:50px}.thumb{height:95px}.thumb-title{display:none}.game-grid{gap:8px}}

const games = [
  {id:'disaster',title:'Natural Disaster Survival',tag:'CLASSIC',genre:'Survival',players:'1.2k',rating:'★ 92%',description:'The sky is changing! Find high ground, dodge the rising flood, and survive the storm.'},
  {id:'pizza',title:'Work at a Pizza Place',tag:'POPULAR',genre:'Roleplay',players:'846',rating:'★ 96%',description:'Clock in at the best pizza shop around. Grab an order and make the delivery!'},
  {id:'crossroads',title:'Crossroads',tag:'CLASSIC',genre:'Adventure',players:'529',rating:'★ 89%',description:'The original hangout. Explore the crossroads and collect the golden bricks.'},
  {id:'obby',title:'Classic Obby',tag:'NEW',genre:'Obby',players:'318',rating:'★ 94%',description:'A bright, bouncy obstacle course made for classic platforming.'}
];
const main = document.querySelector('#mainContent');
const overlay = document.querySelector('#gameOverlay');
let currentPage = 'home';
let activeFilter = 'All';
let searchTerm = '';
let favorites = JSON.parse(localStorage.getItem('classicred-favs') || '["disaster","crossroads","pizza"]');
let recentlyPlayed = JSON.parse(localStorage.getItem('classicred-recent') || '[]');
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function gameCard(game){const art={disaster:'thumb-disaster',pizza:'thumb-pizza',crossroads:'thumb-cross',obby:'thumb-obby'}[game.id];return `<article class="game-card" data-game="${game.id}" tabindex="0" aria-label="Play ${game.title}"><div class="thumb ${art}"><div class="scene"></div><span class="thumb-tag">${game.tag}</span><span class="thumb-players">● ${game.players} playing</span><span class="thumb-title">▶ PLAY</span></div><div class="card-info"><p class="card-title">${game.title}</p><div class="card-meta"><span>${game.genre}</span><span class="rating">${game.rating}</span></div></div></article>`}
function bindCards(){document.querySelectorAll('[data-game]').forEach(el=>{const open=()=>launchGame(el.dataset.game);el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}})})}
function cardGrid(list){return list.length?`<div class="game-grid">${list.map(gameCard).join('')}</div>`:`<div class="empty-state"><strong>No games found</strong>Try a different search or category.</div>`}
function homePage(){main.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">A LITTLE BIT OF 2014, A LOT OF FUN</span><h1>Your next favorite<br>game is right here.</h1><p>Jump into classic worlds, make new memories, and play your way. Welcome back to Classicred.</p><div class="hero-buttons"><button class="btn btn-light" data-game="disaster">▶ &nbsp;Play now</button><button class="btn btn-ghost" data-page="games">Explore games&nbsp; ↗</button></div></div><div class="hero-art" aria-hidden="true"><span class="art-sun">☀</span><div class="art-island"><div class="art-ground"></div><div class="art-road"></div><div class="art-block one"></div><div class="art-block two"></div><div class="art-block three"></div><div class="art-player"><div class="head"></div><div class="torso"></div><div class="legs"><i></i><i></i></div></div></div></div></section><div class="section-head"><div><h2 class="section-title">Featured games</h2><p class="section-sub">Hand-picked classics to get you started</p></div><button class="text-button" data-page="games">See all games&nbsp; →</button></div>${cardGrid(games)}<div class="explore-strip"><div class="strip-icon">✦</div><div><strong>There's a world for everyone</strong><p>Find a new favorite from our growing collection.</p></div><button class="text-button" data-page="games">Browse all&nbsp; →</button></div>`;bindCards()}
function gamesPage(){let list=games.filter(g=>(activeFilter==='All'||g.genre===activeFilter||g.tag===activeFilter.toUpperCase())&&(`${g.title} ${g.genre} ${g.description}`).toLowerCase().includes(searchTerm.toLowerCase()));main.innerHTML=`<div class="page-heading"><div><h1>Games</h1><p>Good games. Good times. Pick your next adventure.</p></div><span class="eyebrow" style="color:#9a9ea5">${games.length} WORLDS</span></div><div class="filter-row">${['All','Classic','Survival','Roleplay','Adventure','Obby'].map(f=>`<button class="filter-chip ${activeFilter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>${cardGrid(list)}`;bindCards();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;gamesPage()})}
