function v(x,y,z){return{x,y,z}}function add(a,b){return v(a.x+b.x,a.y+b.y,a.z+b.z)}function sub(a,b){return v(a.x-b.x,a.y-b.y,a.z-b.z)}function mul(a,n){return v(a.x*n,a.y*n,a.z*n)}function dot(a,b){return a.x*b.x+a.y*b.y+a.z*b.z}function norm(a){let l=Math.hypot(a.x,a.y,a.z)||1;return mul(a,1/l)}
function project(point,width,height){const cam=v(player.x+Math.sin(yaw)*9,player.y+5.4,player.z+Math.cos(yaw)*9),target=v(player.x,player.y+1,player.z-1),forward=norm(sub(target,cam)),right=norm(v(forward.z,0,-forward.x)),up=norm(v(right.y*forward.z-right.z*forward.y,right.z*forward.x-right.x*forward.z,right.x*forward.y-right.y*forward.x));let rel=sub(point,cam),depth=dot(rel,forward);if(depth<.2)return null;const focal=Math.min(width,height)*.88;return{x:width/2+dot(rel,right)*focal/depth,y:height*.48-dot(rel,up)*focal/depth,depth,scale:focal/depth}}
function cubeFaces(b){const x=b.x,y=b.y,z=b.z,w=b.w/2,h=b.h/2,d=b.d/2;const p=[v(x-w,y-h,z-d),v(x+w,y-h,z-d),v(x+w,y+h,z-d),v(x-w,y+h,z-d),v(x-w,y-h,z+d),v(x+w,y-h,z+d),v(x+w,y+h,z+d),v(x-w,y+h,z+d)];return[{ids:[0,1,2,3],color:b.color,shade:.79},{ids:[4,5,6,7],color:b.topColor,shade:1},{ids:[0,4,7,3],color:b.color,shade:.88},{ids:[1,5,6,2],color:b.color,shade:.66},{ids:[3,2,6,7],color:b.topColor,shade:1},{ids:[0,1,5,4],color:b.color,shade:.58}].map(f=>({pts:f.ids.map(i=>p[i]),color:f.color,shade:f.shade}))}
function hexShade(hex,m){if(!hex||hex[0]!=='#')return hex;let h=hex.slice(1);if(h.length===3)h=h.split('').map(x=>x+x).join('');let n=parseInt(h,16);return`rgb(${Math.min(255,((n>>16)&255)*m|0)},${Math.min(255,((n>>8)&255)*m|0)},${Math.min(255,(n&255)*m|0)})`}
function renderWorld(c){const cw=c.canvas.width/(Math.min(devicePixelRatio||1,1.6)),ch=c.canvas.height/(Math.min(devicePixelRatio||1,1.6));const ctx2=c;let sky=ctx2.createLinearGradient(0,0,0,ch);sky.addColorStop(0,world.id==='disaster'&&world.elapsed>world.disasterAt?'#596b7e':'#72c2e9');sky.addColorStop(.64,'#c6ebf4');sky.addColorStop(.65,'#82b668');sky.addColorStop(1,'#4f874b');ctx2.fillStyle=sky;ctx2.fillRect(0,0,cw,ch);
// distant low-poly hills
for(let i=0;i<8;i++){const px=(i*173-(player.x*12)%173);ctx2.fillStyle=['#a2c87b','#88b76b','#96bf73'][i%3];ctx2.beginPath();ctx2.ellipse(px,ch*.62,130,35,0,0,Math.PI*2);ctx2.fill()}
let render=[];for(const b of world.blocks){for(const face of cubeFaces(b)){let pts=face.pts.map(p=>project(p,cw,ch));if(pts.some(p=>!p))continue;render.push({pts,depth:pts.reduce((s,p)=>s+p.depth,0)/4,color:hexShade(face.color,face.shade)})}}
// collectibles and objective markers
world.pickups.forEach((p,i)=>{if(p.done)return;let bob=Math.sin(world.elapsed*3+i)*.15;let pc=project(v(p.x,.95+bob,p.z),cw,ch);if(pc){const s=Math.max(4,Math.min(18,pc.scale*.22));render.push({pts:[{x:pc.x-s,y:pc.y-s,depth:pc.depth},{x:pc.x+s,y:pc.y-s,depth:pc.depth},{x:pc.x+s,y:pc.y+s,depth:pc.depth},{x:pc.x-s,y:pc.y+s,depth:pc.depth}],depth:pc.depth,color:p.kind==='pizza'?'#ffdf66':'#ffe267',glow:true})}});
if(world.goal){const g=project(v(world.goal.x,2.4,world.goal.z),cw,ch);if(g){ctx2.fillStyle='#fff';ctx2.font='bold 10px DM Sans, sans-serif';ctx2.textAlign='center';ctx2.shadowColor='#17202a';ctx2.shadowBlur=6;ctx2.fillText(world.goal.label,g.x,g.y-13);ctx2.shadowBlur=0}}
// rising storm water as a giant shallow slab
if(world.id==='disaster'&&world.elapsed>world.disasterAt){const hh=world.flood;for(const b of [block(0,-.8+hh,0,37,1.5,42,'#398eb5','#71d2e8')])for(const face of cubeFaces(b)){let pts=face.pts.map(p=>project(p,cw,ch));if(!pts.some(p=>!p))render.push({pts,depth:pts.reduce((s,p)=>s+p.depth,0)/4,color:hexShade(face.color,face.shade),water:true})}}
render.sort((a,b)=>b.depth-a.depth);for(const shape of render){ctx2.beginPath();shape.pts.forEach((p,i)=>i?ctx2.lineTo(p.x,p.y):ctx2.moveTo(p.x,p.y));ctx2.closePath();ctx2.fillStyle=shape.color;ctx2.fill();if(shape.glow){ctx2.shadowColor='#ffe889';ctx2.shadowBlur=17;ctx2.fill();ctx2.shadowBlur=0}else if(!shape.water){ctx2.strokeStyle='#263a2c28';ctx2.lineWidth=1;ctx2.stroke()}}
// classic block avatar, assembled as world cubes
const c0=overlay._color||'#c92825',parts=[block(player.x,player.y+.92,player.z,.74,.72,.58,c0),block(player.x,player.y+1.48,player.z,.55,.5,.55,'#efbd91','#ffd0a5'),block(player.x-.21,player.y+.25,player.z,.24,.55,.32,'#30435f','#435a7a'),block(player.x+.21,player.y+.25,player.z,.24,.55,.32,'#30435f','#435a7a'),block(player.x-.48,player.y+.92,player.z,.2,.62,.28,c0),block(player.x+.48,player.y+.92,player.z,.2,.62,.28,c0)];let avatarFaces=[];parts.forEach(b=>cubeFaces(b).forEach(f=>{let pts=f.pts.map(p=>project(p,cw,ch));if(!pts.some(p=>!p))avatarFaces.push({pts,depth:pts.reduce((s,p)=>s+p.depth,0)/4,color:hexShade(f.color,f.shade)})}));avatarFaces.sort((a,b)=>b.depth-a.depth);avatarFaces.forEach(f=>{ctx2.beginPath();f.pts.forEach((p,i)=>i?ctx2.lineTo(p.x,p.y):ctx2.moveTo(p.x,p.y));ctx2.closePath();ctx2.fillStyle=f.color;ctx2.fill();ctx2.strokeStyle='#292b2a44';ctx2.stroke()});
// spawn forcefield ring and aura
if(player.shield>0){const pp=project(v(player.x,player.y+1,player.z),cw,ch);if(pp){ctx2.beginPath();ctx2.ellipse(pp.x,pp.y,pp.scale*.62,pp.scale*.93,0,0,Math.PI*2);ctx2.strokeStyle='#87e8ff';ctx2.lineWidth=3;ctx2.shadowColor='#53d9ff';ctx2.shadowBlur=18;ctx2.stroke();ctx2.shadowBlur=0;ctx2.fillStyle='#b9f4ff22';ctx2.fill()}}
// storm overlay warning
if(world.id==='disaster'&&world.elapsed>world.disasterAt-6){ctx2.fillStyle='#301b1b66';ctx2.fillRect(0,0,cw,38);ctx2.fillStyle='#fff';ctx2.textAlign='center';ctx2.font='800 13px DM Sans';ctx2.fillText(world.elapsed<world.disasterAt?'⚠  STORM APPROACHING — GET TO HIGH GROUND':'⚠  FLASH FLOOD — CLIMB TO SURVIVE',cw/2,24)}
