 function gamesPage(){let list=games.filter(g=>(activeFilter==='All'||g.genre===activeFilter||g.tag===activeFilter.toUpperCase())&&(`${g.title} ${g.genre} ${g.description}`).toLowerCase().includes(searchTerm.toLowerCase()));main.innerHTML=`<div class="page-heading"><div><h1>Games</h1><p>Good games. Good times. Pick your next adventure.</p></div><span class="eyebrow" style="color:#9a9ea5">${games.length} WORLDS</span></div><div class="filter-row">${['All','Classic','Survival','Roleplay','Adventure','Obby'].map(f=>`<button class="filter-chip ${activeFilter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>${cardGrid(list)}`;bindCards();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;gamesPage()})}
 function avatarPage(){main.innerHTML=`<div class="page-heading"><div><h1>Your avatar</h1><p>Your classic look, your way.</p></div></div><div class="simple-panel"><h2>Player</h2><p>Looking good! Pick a shirt color to customize your Classicred avatar.</p><div class="avatar-preview"><div class="avatar-big">🧍</div><div><b>Shirt color</b><div style="margin-top:8px">${['#c92825','#3986ce','#47a36f','#8a61bd','#e39c30','#333944'].map((c,i)=>`<button class="swatch" data-color="${c}" style="background:${c}" aria-label="Color ${i+1}"></button>`).join('')}</div><small style="color:#8b9098">Changes are saved on this device.</small></div></div></div>`;document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{localStorage.setItem('classicred-shirt',b.dataset.color);document.querySelector('.avatar-big').style.background=b.dataset.color;toast('Avatar updated!')});const chosen=localStorage.getItem('classicred-shirt');if(chosen)document.querySelector('.avatar-big').style.background=chosen}

